    const ledger=live.filter(r=>!records.some(x=>(action!=='dismiss-id'||r.id===x.id)&&WishHeld.same(domain,r,x)));
    wishHeldWrite(domain,record,ledger,WishHeld.resolve(resolved,records,'dismissed',Date.now(),jobCreatedAt));
