        for(const side of ['speaker','target'])if(r[side+'Aliases']!==undefined&&(!Array.isArray(r[side+'Aliases'])||r[side+'Aliases'].some(v=>typeof v!=='string')))throw Error('관계 별칭 형식 오류');
