      const custom = !standard && !iso && !yearOnly && !unknown && !era
        ? (legacyExplicit || explicitCustom || (dashedCustom && looksLikeCustomLogDate(dashedCustom[1]) ? dashedCustom : null))
        : null;
      if (!standard && !iso && !yearOnly && !unknown && !era && !custom) continue;

