    const target=structuredClone(targetRaw),source=structuredClone(session.inventory.source);normalizeRoomSlots(target);
    const warnings=['선택 화면에서 읽은 내용의 독립 사본입니다. 원본의 이후 변경과 무관하게 복사하며, 새 방·분기방에서 사용할 내용을 직접 선택하세요.'],changedSlots=[];
    const selected=category=>rows.filter(r=>r.category===category),stats={};
    stats.state=roomCopyStateMerge(target,source,selected('state'),draft.stateMode);if(stats.state.changed)changedSlots.push('currentState');if(stats.state.conflicts)warnings.push(`제목이 같고 내용이 다른 현재상태 ${stats.state.conflicts}개는 현재 방 값을 유지합니다.`);
