          const tail=src.slice(b.sourceStart,b.sourceEnd).match(/\s*$/)[0];
          const next=src.slice(0,b.sourceStart)+newRaw+tail+src.slice(b.sourceEnd),newBlocks=parseDatedLogBlocks(next);
