    const mentioned=new Set(actors.filter(a=>[a.name,...(a.aliases||[])].some(n=>{
      const key=String(n||'').normalize('NFKC').toLocaleLowerCase().trim();
      return key.length>=2&&query.includes(key);
    })).map(a=>a.id));
    const focus=new Set([...present,...mentioned]);
