      if(stopped||!isActive())return;
      const sec=Math.floor((Date.now()-started)/1000);
      const label=(phase==='selecting'?`길이 초과로 기억 선별 중 · ${Number(limit).toLocaleString()}자 한도`:'주입 내용 확인 중…')+(sec>=5?` · ${sec}초 경과`:'');
