function WUIInjectionView(room, candidates) {
 const projection=SecondaryRebuild.projector(room);
 const pending=room.pending, active=safeMemoryItems(room,candidates).map(projection.item).filter(i=>String(i.content||'').trim());
 const groups={}, keys=new Set(active.map(pendingItemIdentity));
 const kindOf=i=>({currentState:'state',threads:'threads',cognition:'cog',speech:'speech',relationship:'relationship',log:'log',lore:'lore',character:'char',extra:'extra'})[injectionCadenceKind(i)] || (i.sourceSlotId==='currentState'?'state':i.slotId==='__lore'?'lore':'misc');
 const row=(i,n,off=false,isActive=true)=>({key:pendingItemIdentity(i)||String(n),rowKey:String(n),kind:kindOf(i),sourceKey:i.sourceKey||'',title:i.title||itemCategory(i),why:i.reason||remainingLabelForItem(i),size:safeForHtmlComment(String(i.content||'').trim()).length,content:i.content||'',off,offReason:off?injectionExclusionReason(room,i,isActive):''});
 // Count every emitted occurrence; the quick-edit map intentionally deduplicates identities.
 const plan=active.map((i,n)=>row(i,n));
 if(pending)for(const entry of quickManageItems(pending))if(!keys.has(entry.key))plan.push(row(entry.item,plan.length,true,entry.active));
 for(const item of plan)if(!item.off)groups[item.kind]=(groups[item.kind]||0)+item.size;
 const parts=contextBlockParts(safeMemoryItems(room,candidates),room),block=parts.block, original=stripOurContextBlock(String(pending?.originalText||'')).text.trimEnd();
 const total=buildInjectedMessage(original,block).length;
 groups.orig=original.length;
 // Only this same block's envelope, headings, separators and instructions are overhead.
 groups.guide=parts.guideChars;
 groups.format=total-original.length-groups.guide-plan.filter(i=>!i.off).reduce((n,i)=>n+i.size,0);
 const hasOriginal=!!pending?.messageId&&!!original;
 const matchesSaved=hasOriginal&&!!block&&block===pending?.contextBlock;
 const verified=matchesSaved&&pending?.verified===true&&!pending?.lastSyncError&&total<=allFitLimit(room);
 return {legacyExclusions:Number(pending?.quickLegacyRemovedItems?.length||0),armed:!!pending,verified,total,max:allFitLimit(room),groups,items:plan,hasCarrier:!!pending?.messageId,hasOriginal,matchesSaved,selection:matchesSaved?pending.selection||null:null,review:room.lastLoreSearch?{method:room.lastLoreSearch.reviewMethod,reason:room.lastLoreSearch.reviewReason,total:room.lastLoreSearch.reviewBaseTotal,limit:room.lastLoreSearch.reviewLimit,at:room.lastLoreSearch.at}:null,...pendingSyncIssue(pending)};
}

function WUIReadMonitor(){
  const room=state.currentRoom;
  if(!room)return {inj:{armed:false,total:0,max:APP.carrierSafeChars},memory:{enabled:false,committed:0,target:0},job:null,reviewCount:0};
  const pending=room.pending,memory=U3.monitor(room);
  const busy=WLOG.view()||(memory.running?{label:memory.jobLabel||'통합 정리 중'}:null)||
    (automaticMemoryJob||automaticLoreJob||R31.busy()?{label:'Wish 작업 중'}:null);
  const cognition=state.v2Cognition;
  const sameRoom=!cognition?.id||String(cognition.id)===String(apiChatIdOf(room));
  return {inj:{armed:!!pending,verified:false,total:Number(pending?.serverChars??pending?.carrierChars??0),max:allFitLimit(room),
      ...pendingSyncIssue(pending)},memory,job:busy,
    reviewCount:sameRoom?(cognition?.reviews||[]).length:0};
}

// Cache only pure text parsing. Pin/exclude/inclusion and knowledge remain live.
const WUILogTextCache=new WeakMap();
